  printExportNamespaceSpecifier(printer: any, node: t.ExportNamespaceSpecifier,) {

  printer.token("*");
  printer.space();
  printer.word("as");
  printer.space();
  printer.print(node.exported, node);
  }

  printExportAllDeclaration(printer: any, node: t.ExportAllDeclaration,) {

  printer.word("export");
  printer.space();
  if (node.exportKind === "type") {
    printer.word("type");
    printer.space();
  }
  printer.token("*");
  printer.space();
  printer.word("from");
  printer.space();
  printer.print(node.source, node);
  printer.printAssertions(node);
  printer.semicolon();
  }

  printExportNamedDeclaration(printer: any, node: t.ExportNamedDeclaration,) {

  if (
    printer.format.decoratorsBeforeExport &&
    isClassDeclaration(node.declaration)
  ) {
    printer.printJoin(node.declaration.decorators, node);
  }

  printer.word("export");
  printer.space();
  this.printExportDeclaration(printer, node);
  }

  printExportDefaultDeclaration(printer: any, node: t.ExportDefaultDeclaration,) {

  if (
    printer.format.decoratorsBeforeExport &&
    isClassDeclaration(node.declaration)
  ) {
    printer.printJoin(node.declaration.decorators, node);
  }

  printer.word("export");
  printer.space();
  printer.word("default");
  printer.space();
  this.printExportDeclaration(printer, node);
  }

  printExportDeclaration(printer: any, node: any) {

  if (node.declaration) {
    const declar = node.declaration;
    printer.print(declar, node);
    if (!isStatement(declar)) printer.semicolon();
  } else {
    if (node.exportKind === "type") {
      printer.word("type");
      printer.space();
    }

    const specifiers = node.specifiers.slice(0);

    // print "special" specifiers first
    let hasSpecial = false;
    for (;;) {
      const first = specifiers[0];
      if (
        isExportDefaultSpecifier(first) ||
        isExportNamespaceSpecifier(first)
      ) {
        hasSpecial = true;
        printer.print(specifiers.shift(), node);
        if (specifiers.length) {
          printer.token(",");
          printer.space();
        }
      } else {
        break;
      }
    }

    if (specifiers.length || (!specifiers.length && !hasSpecial)) {
      printer.token("{");
      if (specifiers.length) {
        printer.space();
        printer.printList(specifiers, node);
        printer.space();
      }
      printer.token("}");
    }

    if (node.source) {
      printer.space();
      printer.word("from");
      printer.space();
      printer.print(node.source, node);
      printer.printAssertions(node);
    }

    printer.semicolon();
  }
  }

  printImportDeclaration(printer: any, node: t.ImportDeclaration) {

  printer.word("import");
  printer.space();

  const isTypeKind = node.importKind === "type" || node.importKind === "typeof";
  if (isTypeKind) {
    printer.word(node.importKind);
    printer.space();
  }

  const specifiers = node.specifiers.slice(0);
  const hasSpecifiers = !!specifiers.length;
  // print "special" specifiers first. The loop condition is constant,
  // but there is a "break" in the body.
  while (hasSpecifiers) {
    const first = specifiers[0];
    if (isImportDefaultSpecifier(first) || isImportNamespaceSpecifier(first)) {
      printer.print(specifiers.shift(), node);
      if (specifiers.length) {
        printer.token(",");
        printer.space();
      }
    } else {
      break;
    }
  }

  if (specifiers.length) {
    printer.token("{");
    printer.space();
    printer.printList(specifiers, node);
    printer.space();
    printer.token("}");
  } else if (isTypeKind && !hasSpecifiers) {
    printer.token("{");
    printer.token("}");
  }

  if (hasSpecifiers || isTypeKind) {
    printer.space();
    printer.word("from");
    printer.space();
  }

  printer.print(node.source, node);

  printer.printAssertions(node);
  if (!process.env.BABEL_8_BREAKING) {
    // @ts-expect-error
    if (node.attributes?.length) {
      printer.space();
      printer.word("with");
      printer.space();
      // @ts-expect-error
      printer.printList(node.attributes, node);
    }
  }

  printer.semicolon();
  }

  printImportAttribute(printer: any, node: t.ImportAttribute) {

  printer.print(node.key);
  printer.token(":");
  printer.space();
  printer.print(node.value);
  }

  printImportNamespaceSpecifier(printer: any, node: t.ImportNamespaceSpecifier,) {

  printer.token("*");
  printer.space();
  printer.word("as");
  printer.space();
  printer.print(node.local, node);
  }

  print_params(printer: any, node: any) {

  printer.print(node.typeParameters, node);
  printer.token("(");
  this.print_parameters(printer, node.params, node);
  printer.token(")");

  printer.print(node.returnType, node);
  }

  print_parameters(printer: any, parameters, parent) {

  for (let i = 0; i < parameters.length; i++) {
    this.print_param(printer, parameters[i], parent);

    if (i < parameters.length - 1) {
      printer.token(",");
      printer.space();
    }
  }
  }

  print_param(printer: any, parameter, parent?) {

  printer.printJoin(parameter.decorators, parameter);
  printer.print(parameter, parent);
  if (parameter.optional) printer.token("?"); // TS / flow
  printer.print(parameter.typeAnnotation, parameter); // TS / flow
  }

  print_methodHead(printer: any, node: any) {

  const kind = node.kind;
  const key = node.key;

  if (kind === "get" || kind === "set") {
    printer.word(kind);
    printer.space();
  }

  if (node.async) {
    // ensure `async` is in the same line with property name
    printer._catchUp("start", key.loc);
    printer.word("async");
    printer.space();
  }

  if (kind === "method" || kind === "init") {
    if (node.generator) {
      printer.token("*");
    }
  }

  if (node.computed) {
    printer.token("[");
    printer.print(key, node);
    printer.token("]");
  } else {
    printer.print(key, node);
  }

  if (node.optional) {
    // TS
    printer.token("?");
  }

  this.print_params(printer, node);
  }

  print_predicate(printer: any, node: any) {

  if (node.predicate) {
    if (!node.returnType) {
      printer.token(":");
    }
    printer.space();
    printer.print(node.predicate, node);
  }
  }

  print_functionHead(printer: any, node: any) {

  if (node.async) {
    printer.word("async");
    printer.space();
  }
  printer.word("function");
  if (node.generator) printer.token("*");
  printer.printInnerComments(node);

  printer.space();
  if (node.id) {
    printer.print(node.id, node);
  }

  this.print_params(printer, node);
  this.print_predicate(printer, node);
  }

  printFunctionExpression(printer: any, node: t.FunctionExpression) {

  this.print_functionHead(printer, node);
  printer.space();
  printer.print(node.body, node);
  }

  printArrowFunctionExpression(printer: any, node: t.ArrowFunctionExpression,) {

  if (node.async) {
    printer.word("async");
    printer.space();
  }

  const firstParam = node.params[0];

  // Try to avoid printing parens in simple cases, but only if we're pretty
  // sure that they aren't needed by type annotations or potential newlines.
  if (
    !printer.format.retainLines &&
    // Auxiliary comments can introduce unexpected newlines
    !printer.format.auxiliaryCommentBefore &&
    !printer.format.auxiliaryCommentAfter &&
    node.params.length === 1 &&
    isIdentifier(firstParam) &&
    !this.printhasTypesOrComments(printer, node, firstParam)
  ) {
    printer.print(firstParam, node);
  } else {
    this.print_params(printer, node);
  }

  this.print_predicate(printer, node);

  printer.space();
  printer.token("=>");
  printer.space();

  printer.print(node.body, node);
  }

  printhasTypesOrComments(printer: any, node: t.ArrowFunctionExpression,
  param: t.Identifier,) {

  return !!(
    node.typeParameters ||
    node.returnType ||
    node.predicate ||
    param.typeAnnotation ||
    param.optional ||
    param.leadingComments?.length ||
    param.trailingComments?.length
  );
  }

  printForInStatement(printer: any, node: any) {
    printer.word("for");
    printer.space();
    printer.token("(");
    printer.print(node.left, node);
    printer.space();
    printer.word("in");
    printer.space();
    printer.print(node.right, node);
    printer.token(")");
    printer.printBlock(node);
  }

  printForOfStatement(printer: any, node: any) {
    printer.word("for");
    printer.space();
    if (node.await) {
      printer.word("await");
      printer.space();
    }
    printer.token("(");
    printer.print(node.left, node);
    printer.space();
    printer.word("of");
    printer.space();
    printer.print(node.right, node);
    printer.token(")");
    printer.printBlock(node);
  }

  printContinueStatement(printer: any, node: any) {
    printer.word("continue");
    const label = node["label"];
    if (label) {
      printer.space();
      const terminatorState = printer.startTerminatorless(true);
      printer.print(label, node);
      printer.endTerminatorless(terminatorState);
    }
    printer.semicolon();
  }

  printReturnStatement(printer: any, node: any) {
    printer.word("return");
    const label = node["argument"];
    if (label) {
      printer.space();
      const terminatorState = printer.startTerminatorless(false);
      printer.print(label, node);
      printer.endTerminatorless(terminatorState);
    }
    printer.semicolon();
  }

  printBreakStatement(printer: any, node: any) {
    printer.word("break");
    const label = node["label"];
    if (label) {
      printer.space();
      const terminatorState = printer.startTerminatorless(true);
      printer.print(label, node);
      printer.endTerminatorless(terminatorState);
    }
    printer.semicolon();
  }

  printThrowStatement(printer: any, node: any) {
    printer.word("throw");
    const label = node["argument"];
    if (label) {
      printer.space();
      const terminatorState = printer.startTerminatorless(false);
      printer.print(label, node);
      printer.endTerminatorless(terminatorState);
    }
    printer.semicolon();
  }

  printYieldExpression(printer: any, node: any) {
    printer.word("yield");
    if (node.delegate) {
      printer.token("*");
    }
    if (node.argument) {
      printer.space();
      const terminatorState = printer.startTerminatorless();
      printer.print(node.argument, node);
      printer.endTerminatorless(terminatorState);
    }
  }

  printAwaitExpression(printer: any, node: any) {
    printer.word("await");
    if (node.delegate) {
      printer.token("*");
    }
    if (node.argument) {
      printer.space();
      const terminatorState = printer.startTerminatorless();
      printer.print(node.argument, node);
      printer.endTerminatorless(terminatorState);
    }
  }

  parenNullableTypeAnnotation(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return isArrayTypeAnnotation(parent);
  }

  parenFunctionTypeAnnotation(
  node: any,
  parent: any,
  printStack: Array<any>,
) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return (
    // (() => A) | (() => B)
    isUnionTypeAnnotation(parent) ||
    // (() => A) & (() => B)
    isIntersectionTypeAnnotation(parent) ||
    // (() => A)[]
    isArrayTypeAnnotation(parent) ||
    // <T>(A: T): (T => T[]) => B => [A, B]
    (isTypeAnnotation(parent) &&
      // Check grandparent
      isArrowFunctionExpression(printStack[printStack.length - 3]))
  );
  }

  parenUpdateExpression(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return hasPostfixPart(node, parent) || isClassExtendsClause(node, parent);
  }

  parenObjectExpression(
  node: any,
  parent: any,
  printStack: Array<any>,
) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return isFirstInContext(printStack, {
    expressionStatement: true,
    arrowBody: true,
  });
  }

  parenDoExpression(
  node: any,
  parent: any,
  printStack: Array<any>,
) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  // `async do` can start an expression statement
  return (
    !node.async && isFirstInContext(printStack, { expressionStatement: true })
  );
  }

  parenBinary(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  if (
    node.operator === "**" &&
    isBinaryExpression(parent, { operator: "**" })
  ) {
    return parent.left === node;
  }

  if (isClassExtendsClause(node, parent)) {
    return true;
  }

  if (
    hasPostfixPart(node, parent) ||
    isUnaryLike(parent) ||
    isAwaitExpression(parent)
  ) {
    return true;
  }

  if (isBinary(parent)) {
    const parentOp = parent.operator;
    const parentPos = PRECEDENCE[parentOp];

    const nodeOp = node.operator;
    const nodePos = PRECEDENCE[nodeOp];

    if (
      // Logical expressions with the same precedence don't need parens.
      (parentPos === nodePos &&
        parent.right === node &&
        !isLogicalExpression(parent)) ||
      parentPos > nodePos
    ) {
      return true;
    }
  }
  }

  parenUnionTypeAnnotation(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return (
    isArrayTypeAnnotation(parent) ||
    isNullableTypeAnnotation(parent) ||
    isIntersectionTypeAnnotation(parent) ||
    isUnionTypeAnnotation(parent)
  );
  }

  parenOptionalIndexedAccessType(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return isIndexedAccessType(parent, { objectType: node });
  }

  parenTSAsExpression() {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return true;
  }

  parenTSTypeAssertion() {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return true;
  }

  parenTSUnionType(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return (
    isTSArrayType(parent) ||
    isTSOptionalType(parent) ||
    isTSIntersectionType(parent) ||
    isTSUnionType(parent) ||
    isTSRestType(parent)
  );
  }

  parenTSInferType(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return isTSArrayType(parent) || isTSOptionalType(parent);
  }

  parenBinaryExpression(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  // let i = (1 in []);
  // for ((1 in []);;);
  return (
    node.operator === "in" && (isVariableDeclarator(parent) || isFor(parent))
  );
  }

  parenSequenceExpression(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  if (
    // Although parentheses wouldn"t hurt around sequence
    // expressions in the head of for loops, traditional style
    // dictates that e.g. i++, j++ should not be wrapped with
    // parentheses.
    isForStatement(parent) ||
    isThrowStatement(parent) ||
    isReturnStatement(parent) ||
    (isIfStatement(parent) && parent.test === node) ||
    (isWhileStatement(parent) && parent.test === node) ||
    (isForInStatement(parent) && parent.right === node) ||
    (isSwitchStatement(parent) && parent.discriminant === node) ||
    (isExpressionStatement(parent) && parent.expression === node)
  ) {
    return false;
  }

  // Otherwise err on the side of overparenthesization, adding
  // explicit exceptions above if this proves overzealous.
  return true;
  }

  parenYieldExpression(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return (
    isBinary(parent) ||
    isUnaryLike(parent) ||
    hasPostfixPart(node, parent) ||
    (isAwaitExpression(parent) && isYieldExpression(node)) ||
    (isConditionalExpression(parent) && node === parent.test) ||
    isClassExtendsClause(node, parent)
  );
  }

  parenClassExpression(
  node: any,
  parent: any,
  printStack: Array<any>,
) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return isFirstInContext(printStack, {
    expressionStatement: true,
    exportDefault: true,
  });
  }

  parenUnaryLike(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return (
    hasPostfixPart(node, parent) ||
    isBinaryExpression(parent, { operator: "**", left: node }) ||
    isClassExtendsClause(node, parent)
  );
  }

  parenFunctionExpression(
  node: any,
  parent: any,
  printStack: Array<any>,
) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return isFirstInContext(printStack, {
    expressionStatement: true,
    exportDefault: true,
  });
  }

  parenArrowFunctionExpression(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return isExportDeclaration(parent) || ConditionalExpression(node, parent);
  }

  parenConditionalExpression(node: any, parent?) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  if (
    isUnaryLike(parent) ||
    isBinary(parent) ||
    isConditionalExpression(parent, { test: node }) ||
    isAwaitExpression(parent) ||
    isTSTypeAssertion(parent) ||
    isTSAsExpression(parent)
  ) {
    return true;
  }

  return UnaryLike(node, parent);
  }

  parenOptionalMemberExpression(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  return (
    isCallExpression(parent, { callee: node }) ||
    isMemberExpression(parent, { object: node })
  );
  }

  parenAssignmentExpression(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  if (isObjectPattern(node.left)) {
    return true;
  } else {
    return ConditionalExpression(node, parent);
  }
  }

  parenLogicalExpression(node: any, parent: any) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  switch (node.operator) {
    case "||":
      if (!isLogicalExpression(parent)) return false;
      return parent.operator === "??" || parent.operator === "&&";
    case "&&":
      return isLogicalExpression(parent, { operator: "??" });
    case "??":
      return isLogicalExpression(parent) && parent.operator !== "??";
  }
  }

  parenIdentifier(
  node: t.Identifier,
  parent: t.Node,
  printStack: Array<t.Node>,
) {
    this._parenDecision.lastType = "parenDecision";
    this._parenDecision.depth += 1;
    this._parenDecision.seen += 1;

  // Non-strict code allows the identifier `let`, but it cannot occur as-is in
  // certain contexts to avoid ambiguity with contextual keyword `let`.
  if (node.name === "let") {
    // Some contexts only forbid `let [`, so check if the next token would
    // be the left bracket of a computed member expression.
    const isFollowedByBracket =
      isMemberExpression(parent, {
        object: node,
        computed: true,
      }) ||
      isOptionalMemberExpression(parent, {
        object: node,
        computed: true,
        optional: false,
      });
    return isFirstInContext(printStack, {
      expressionStatement: isFollowedByBracket,
      forHead: isFollowedByBracket,
      forInHead: isFollowedByBracket,
      forOfHead: true,
    });
  }

  // ECMAScript specifically forbids a for-of loop from starting with the
  // token sequence `for (async of`, because it would be ambiguous with
  // `for (async of => {};;)`, so we need to add extra parentheses.
  //
  // If the parent is a for-await-of loop (i.e. parent.await === true), the
  // parentheses aren't strictly needed, but we add them anyway because
  // some tools (including earlier Babel versions) can't parse
  // `for await (async of [])` without them.
  return (
    node.name === "async" && isForOfStatement(parent) && node === parent.left
  );
  }

  printcrawl(
  node: t.Node,
  state: { hasCall?: boolean; hasFunction?: boolean; hasHelper?: boolean } = {},
) {

  if (isMemberExpression(node) || isOptionalMemberExpression(node)) {
    this.printcrawl(node.object, state);
    if (node.computed) this.printcrawl(node.property, state);
  } else if (isBinary(node) || isAssignmentExpression(node)) {
    this.printcrawl(node.left, state);
    this.printcrawl(node.right, state);
  } else if (isCallExpression(node) || isOptionalCallExpression(node)) {
    state.hasCall = true;
    this.printcrawl(node.callee, state);
  } else if (isFunction(node)) {
    state.hasFunction = true;
  } else if (isIdentifier(node)) {
    // @ts-expect-error todo(flow->ts): node.callee is not really expected here…
    state.hasHelper = state.hasHelper || this.printisHelper(node.callee);
  }

  return state;
  }

  printisHelper(node: t.Node) {

  if (isMemberExpression(node)) {
    return this.printisHelper(node.object) || this.printisHelper(node.property);
  } else if (isIdentifier(node)) {
    return node.name === "require" || node.name[0] === "_";
  } else if (isCallExpression(node)) {
    return this.printisHelper(node.callee);
  } else if (isBinary(node) || isAssignmentExpression(node)) {
    return (
      (isIdentifier(node.left) && this.printisHelper(node.left)) || this.printisHelper(node.right)
    );
  } else {
    return false;
  }
  }

  printisType(node) {

  return (
    isLiteral(node) ||
    isObjectExpression(node) ||
    isArrayExpression(node) ||
    isIdentifier(node) ||
    isMemberExpression(node)
  );
  }

  whitespaceAssignmentExpression(node: any, parent?: any) {
    const state = this.printcrawl(node.right);
    if ((state.hasCall && state.hasHelper) || state.hasFunction) {
      this._whitespaceDecision.before = !!state.hasFunction;
      this._whitespaceDecision.after = true;
      return {
        before: state.hasFunction,
        after: true,
      };
    }
  }

  whitespaceSwitchCase(node: any, parent?: any) {
    this._whitespaceDecision.before = !!node.consequent.length || parent.cases[0] === node;
    this._whitespaceDecision.after = !node.consequent.length && parent.cases[parent.cases.length - 1] === node;
    return {
      before: this._whitespaceDecision.before,
      after: this._whitespaceDecision.after,
    };
  }

  whitespaceLogicalExpression(node: any, parent?: any) {
    if (isFunction(node.left) || isFunction(node.right)) {
      this._whitespaceDecision.after = true;
      return {
        after: true,
      };
    }
  }

  whitespaceLiteral(node: any, parent?: any) {
    if (isStringLiteral(node) && node.value === "use strict") {
      this._whitespaceDecision.after = true;
      return {
        after: true,
      };
    }
  }

  whitespaceCallExpression(node: any, parent?: any) {
    if (isFunction(node.callee) || this.printisHelper(node)) {
      this._whitespaceDecision.before = true;
      this._whitespaceDecision.after = true;
      return {
        before: true,
        after: true,
      };
    }
  }

  whitespaceOptionalCallExpression(node: any, parent?: any) {
    if (isFunction(node.callee)) {
      this._whitespaceDecision.before = true;
      this._whitespaceDecision.after = true;
      return {
        before: true,
        after: true,
      };
    }
  }

  whitespaceVariableDeclaration(node: any, parent?: any) {
    for (let i = 0; i < node.declarations.length; i++) {
      const declar = node.declarations[i];

      let enabled = this.printisHelper(declar.id) && !this.printisType(declar.init);
      if (!enabled) {
        const state = this.printcrawl(declar.init);
        enabled = (this.printisHelper(declar.init) && state.hasCall) || state.hasFunction;
      }

      if (enabled) {
        this._whitespaceDecision.before = true;
        this._whitespaceDecision.after = true;
        return {
          before: true,
          after: true,
        };
      }
    }
  }

  whitespaceIfStatement(node: any, parent?: any) {
    if (isBlockStatement(node.consequent)) {
      this._whitespaceDecision.before = true;
      this._whitespaceDecision.after = true;
      return {
        before: true,
        after: true,
      };
    }
  }

  whitespaceObjectProperty(node: any, parent?: any) {
    if (parent.properties[0] === node) {
      this._whitespaceDecision.before = true;
      return {
        before: true,
      };
    }
  }

  whitespaceObjectTypeCallProperty(node: any, parent?: any) {
    if (parent.callProperties[0] === node && !parent.properties?.length) {
      this._whitespaceDecision.before = true;
      return {
        before: true,
      };
    }
  }

  whitespaceObjectTypeIndexer(node: any, parent?: any) {
    if (
      parent.indexers[0] === node &&
      !parent.properties?.length &&
      !parent.callProperties?.length
    ) {
      this._whitespaceDecision.before = true;
      return {
        before: true,
      };
    }
  }

  whitespaceObjectTypeInternalSlot(node: any, parent?: any) {
    if (
      parent.internalSlots[0] === node &&
      !parent.properties?.length &&
      !parent.callProperties?.length &&
      !parent.indexers?.length
